import argparse
import json

from fastapi import FastAPI, Header, HTTPException, Request, Response
from pydantic import BaseModel, Field

from app.rules import order_rules
from app.store import batches, orders, payment_rollbacks, refunds
from app.store.db import connect, migrate
from app.store.refunds import ConflictError, OrderNotFound
from app.usecase import batch_import
from app.usecase.batch_import import CsvFormatError

app = FastAPI(title="settlement-ledger")

class OrderIn(BaseModel):
    tenant: str = Field(min_length=1)
    order_id: str = Field(min_length=1)
    amount_cents: int = Field(gt=0)
    currency: str = Field(min_length=3, max_length=3)

class PaymentIn(BaseModel):
    amount_cents: int = Field(gt=0)

@app.get("/health")
def health() -> dict:
    conn = connect()
    try:
        conn.execute("SELECT 1")
    finally:
        conn.close()
    return {"status": "ok"}

@app.post("/orders", status_code=201)
def create_order(body: OrderIn) -> dict:
    order_rules.assert_currency(body.currency)
    try:
        orders.insert(body.tenant, body.order_id, body.amount_cents, body.currency)
    except Exception as error:
        if "UNIQUE" in str(error):
            raise HTTPException(status_code=409, detail="order already accepted")
        raise
    return orders.get(body.tenant, body.order_id)

@app.get("/orders/{order_id}")
def read_order(order_id: str, x_tenant: str = Header(default="", alias=None)) -> dict:
    tenant = x_tenant or ""
    if not tenant:
        raise HTTPException(status_code=400, detail="tenant header is required")
    order = orders.get(tenant, order_id)
    if order is None:
        raise HTTPException(status_code=404, detail="order not found")
    return order

@app.get("/orders")
def search_orders(request: Request, x_tenant: str = Header(default="")) -> dict:
    # 条件检索入口：租户仍由 X-Tenant 声明，所有过滤都强制限定在本租户内，
    # 跨租户检索一律得到空结果，无法据此判断其他租户是否存在匹配订单。
    tenant = _require_tenant(x_tenant)
    q = request.query_params

    status = _optional_str(q.get("status"))
    if status is not None and status not in orders.SEARCHABLE_STATUSES:
        raise HTTPException(status_code=400, detail="status must be 'accepted' or 'settled'")

    amount_min = _parse_bound(q.get("amount_min"), "amount_min")
    amount_max = _parse_bound(q.get("amount_max"), "amount_max")
    outstanding_min = _parse_bound(q.get("outstanding_min"), "outstanding_min")
    outstanding_max = _parse_bound(q.get("outstanding_max"), "outstanding_max")
    if amount_min is not None and amount_max is not None and amount_min > amount_max:
        raise HTTPException(status_code=400, detail="amount_min must not be greater than amount_max")
    if outstanding_min is not None and outstanding_max is not None and outstanding_min > outstanding_max:
        raise HTTPException(
            status_code=400,
            detail="outstanding_min must not be greater than outstanding_max",
        )

    # 每页大小由调用方显式指定，必须为正整数。
    page_size_raw = q.get("page_size")
    if not _non_empty_str(page_size_raw):
        raise HTTPException(status_code=400, detail="page_size is required and must be a positive integer")
    page_size = _parse_positive_int(page_size_raw, "page_size")

    cursor = _optional_str(q.get("cursor"))

    try:
        page, total, next_cursor = orders.search(
            tenant,
            status=status,
            amount_min=amount_min,
            amount_max=amount_max,
            outstanding_min=outstanding_min,
            outstanding_max=outstanding_max,
            cursor=cursor,
            limit=page_size,
        )
    except orders.InvalidCursor:
        # 游标指向本租户不存在的订单：参数错误，与内部错误区分。
        raise HTTPException(status_code=400, detail="cursor does not point to an order of this tenant")
    return {
        "orders": page,
        "total": total,
        "page_size": page_size,
        "next_cursor": next_cursor,
        "has_next": next_cursor is not None,
    }

def _optional_str(value: str | None) -> str | None:
    if value is None:
        return None
    value = value.strip()
    return value or None

def _parse_bound(value: str | None, name: str) -> int | None:
    # 区间端点可缺省；给出时必须是非负整数（含边界，0 合法），浮点/负数/非数字一律参数错误。
    if not _non_empty_str(value):
        return None
    return _parse_non_negative_int(value, name)

def _parse_non_negative_int(value: str, name: str) -> int:
    try:
        parsed = int(value)
    except (TypeError, ValueError):
        raise HTTPException(status_code=400, detail=f"{name} must be a non-negative integer")
    if isinstance(parsed, bool) or parsed < 0:
        raise HTTPException(status_code=400, detail=f"{name} must be a non-negative integer")
    return parsed

def _parse_positive_int(value: str, name: str) -> int:
    try:
        parsed = int(value)
    except (TypeError, ValueError):
        raise HTTPException(status_code=400, detail=f"{name} must be a positive integer")
    if isinstance(parsed, bool) or parsed <= 0:
        raise HTTPException(status_code=400, detail=f"{name} must be a positive integer")
    return parsed

@app.post("/orders/{order_id}/payments")
def add_payment(order_id: str, body: PaymentIn, x_tenant: str = Header(default="")) -> dict:
    if not x_tenant:
        raise HTTPException(status_code=400, detail="tenant header is required")
    try:
        order = orders.add_payment(x_tenant, order_id, body.amount_cents)
    except ValueError as error:
        raise HTTPException(status_code=409, detail=str(error))
    if order is None:
        raise HTTPException(status_code=404, detail="order not found")
    return order

@app.post("/orders/batch-accept", status_code=201)
async def accept_orders_batch(request: Request, response: Response) -> dict:
    # 两种导入形态：application/json 携带 csv 文本字段；其余 Content-Type 直接上传 CSV 字节，
    # 租户与批次标识通过查询参数 tenant、batch_id 声明。
    if request.headers.get("content-type", "").startswith("application/json"):
        body = await _json_body(request)
        tenant = body.get("tenant")
        batch_id = body.get("batch_id")
        csv_text = body.get("csv")
        if not (_non_empty_str(tenant) and _non_empty_str(batch_id)):
            raise HTTPException(status_code=400, detail="tenant and batch_id are required")
        if not _non_empty_str(csv_text):
            raise HTTPException(status_code=400, detail="csv is required")
        raw = csv_text.encode("utf-8")
    else:
        tenant = request.query_params.get("tenant", "")
        batch_id = request.query_params.get("batch_id", "")
        if not (_non_empty_str(tenant) and _non_empty_str(batch_id)):
            raise HTTPException(status_code=400, detail="tenant and batch_id query parameters are required")
        raw = await request.body()
        if not raw:
            raise HTTPException(status_code=400, detail="csv body is required")

    try:
        result, processed = batch_import.accept_batch(tenant, batch_id, raw)
    except CsvFormatError as error:
        # CSV 格式非法：整批拒绝，不受理任何行。
        raise HTTPException(status_code=400, detail=str(error))
    except batches.InputMismatch as error:
        raise HTTPException(status_code=409, detail=str(error))
    if not processed:
        # 同一批次身份重试/重放：不重复受理，返回既有结果（HTTP 200）。
        response.status_code = 200
    return result

@app.get("/batches/{batch_id}")
def read_batch(batch_id: str, x_tenant: str = Header(default="")) -> dict:
    tenant = _require_tenant(x_tenant)
    result = batches.get(tenant, batch_id)
    if result is None:
        # 跨租户查询一律按不存在处理，不泄漏批次是否存在。
        raise HTTPException(status_code=404, detail="batch not found")
    return result

def _require_tenant(x_tenant: str) -> str:
    if not x_tenant:
        raise HTTPException(status_code=400, detail="tenant header is required")
    return x_tenant

async def _json_body(request: Request) -> dict:
    try:
        body = await request.json()
    except (json.JSONDecodeError, UnicodeDecodeError):
        raise HTTPException(status_code=400, detail="invalid JSON body")
    if not isinstance(body, dict):
        raise HTTPException(status_code=400, detail="invalid JSON body")
    return body

def _non_empty_str(value) -> bool:
    return isinstance(value, str) and len(value) > 0

def _positive_int(value) -> bool:
    # 排除 bool：True/False 在 Python 中是 int 子类，不是合法金额。
    return isinstance(value, int) and not isinstance(value, bool) and value > 0

@app.post("/refunds", status_code=201)
async def register_refund(request: Request, response: Response) -> dict:
    body = await _json_body(request)
    tenant = body.get("tenant")
    refund_id = body.get("refund_id")
    order_id = body.get("order_id")
    amount_cents = body.get("amount_cents")
    reason = body.get("reason")
    if not (_non_empty_str(tenant) and _non_empty_str(refund_id) and _non_empty_str(order_id)):
        raise HTTPException(status_code=400, detail="tenant, refund_id and order_id are required")
    if not _non_empty_str(reason):
        raise HTTPException(status_code=400, detail="reason is required")
    if not _positive_int(amount_cents):
        raise HTTPException(status_code=400, detail="amount_cents must be a positive integer")

    try:
        refund, created = refunds.register(tenant, refund_id, order_id, amount_cents, reason)
    except OrderNotFound:
        # 订单不存在或不属于本租户统一按参数错误处理，不泄漏订单是否存在。
        raise HTTPException(status_code=400, detail="order not found")
    except ConflictError as error:
        raise HTTPException(status_code=409, detail=str(error))
    if not created:
        # 同一业务身份重复登记：不新建单据、不重复退款，返回既有单据及当前状态。
        response.status_code = 200
    return refund

@app.get("/refunds/{refund_id}")
def read_refund(refund_id: str, x_tenant: str = Header(default="")) -> dict:
    tenant = _require_tenant(x_tenant)
    refund = refunds.get(tenant, refund_id)
    if refund is None:
        raise HTTPException(status_code=404, detail="refund not found")
    return refund

@app.post("/refunds/{refund_id}/review")
async def review_refund(refund_id: str, request: Request, x_tenant: str = Header(default="")) -> dict:
    tenant = _require_tenant(x_tenant)
    body = await _json_body(request)
    decision = body.get("decision")
    if decision not in ("approve", "reject"):
        raise HTTPException(status_code=400, detail="decision must be 'approve' or 'reject'")
    try:
        refund = refunds.review(tenant, refund_id, decision == "approve")
    except ConflictError as error:
        raise HTTPException(status_code=409, detail=str(error))
    if refund is None:
        raise HTTPException(status_code=404, detail="refund not found")
    return refund

@app.post("/refunds/{refund_id}/reverse")
def reverse_refund(refund_id: str, x_tenant: str = Header(default="")) -> dict:
    tenant = _require_tenant(x_tenant)
    try:
        refund = refunds.reverse(tenant, refund_id)
    except ConflictError as error:
        raise HTTPException(status_code=409, detail=str(error))
    if refund is None:
        raise HTTPException(status_code=404, detail="refund not found")
    return refund

@app.post("/payment-rollbacks", status_code=201)
async def register_payment_rollback(request: Request, response: Response) -> dict:
    body = await _json_body(request)
    tenant = body.get("tenant")
    rollback_id = body.get("rollback_id")
    order_id = body.get("order_id")
    amount_cents = body.get("amount_cents")
    if not (_non_empty_str(tenant) and _non_empty_str(rollback_id) and _non_empty_str(order_id)):
        raise HTTPException(status_code=400, detail="tenant, rollback_id and order_id are required")
    if not _positive_int(amount_cents):
        raise HTTPException(status_code=400, detail="amount_cents must be a positive integer")

    try:
        rollback, created = payment_rollbacks.register(tenant, rollback_id, order_id, amount_cents)
    except payment_rollbacks.OrderNotFound:
        # 订单不存在或不属于本租户统一按参数错误处理，不泄漏订单是否存在。
        raise HTTPException(status_code=400, detail="order not found")
    except payment_rollbacks.InvalidAmountError as error:
        raise HTTPException(status_code=400, detail=str(error))
    except payment_rollbacks.ConflictError as error:
        raise HTTPException(status_code=409, detail=str(error))
    if not created:
        # 同一业务身份重复请求：不新建回退、不重复退回金额，返回既有回退结果。
        response.status_code = 200
    return rollback

@app.get("/payment-rollbacks/{rollback_id}")
def read_payment_rollback(rollback_id: str, x_tenant: str = Header(default="")) -> dict:
    tenant = _require_tenant(x_tenant)
    rollback = payment_rollbacks.get(tenant, rollback_id)
    if rollback is None:
        raise HTTPException(status_code=404, detail="payment rollback not found")
    return rollback

def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--port", type=int, default=8000)
    parser.add_argument("--migrate", action="store_true")
    args = parser.parse_args()
    migrate()
    if args.migrate:
        print("migrated")
        return
    import uvicorn
    uvicorn.run(app, host="127.0.0.1", port=args.port)

if __name__ == "__main__":
    main()

from app.store.db import connect

PENDING = "pending"
APPROVED = "approved"
REJECTED = "rejected"
REVERSED = "reversed"


class RefundError(Exception):
    pass


class ConflictError(RefundError):
    pass


class OrderNotFound(RefundError):
    pass


def _rollback(conn) -> None:
    if conn.in_transaction:
        conn.execute("ROLLBACK")


def _to_dict(row) -> dict:
    return {
        "tenant": row["tenant"],
        "refund_id": row["refund_id"],
        "order_id": row["order_id"],
        "amount_cents": row["amount_cents"],
        "reason": row["reason"],
        "status": row["status"],
    }


def get(tenant: str, refund_id: str) -> dict | None:
    conn = connect()
    try:
        row = conn.execute(
            "SELECT tenant, refund_id, order_id, amount_cents, reason, status "
            "FROM refunds WHERE tenant=? AND refund_id=?",
            (tenant, refund_id),
        ).fetchone()
    finally:
        conn.close()
    return None if row is None else _to_dict(row)


def register(tenant: str, refund_id: str, order_id: str, amount_cents: int, reason: str) -> tuple[dict, bool]:
    """登记退款单。返回(退款单, 是否新建)；业务身份重复时返回既有单据及当前状态。"""
    conn = connect()
    try:
        conn.execute("BEGIN IMMEDIATE")
        existing = conn.execute(
            "SELECT tenant, refund_id, order_id, amount_cents, reason, status "
            "FROM refunds WHERE tenant=? AND refund_id=?",
            (tenant, refund_id),
        ).fetchone()
        if existing is not None:
            conn.execute("COMMIT")
            return _to_dict(existing), False

        order = conn.execute(
            "SELECT amount_cents, paid_cents FROM orders WHERE tenant=? AND order_id=?",
            (tenant, order_id),
        ).fetchone()
        if order is None:
            raise OrderNotFound("order not found")

        # 待审核 + 已批准未冲正的退款合计视为已占用额度，保证任意逐笔批准顺序下都不会超出已收。
        reserved = conn.execute(
            "SELECT COALESCE(SUM(CASE WHEN status IN ('pending','approved') "
            "THEN amount_cents ELSE 0 END),0) AS reserved "
            "FROM refunds WHERE tenant=? AND order_id=?",
            (tenant, order_id),
        ).fetchone()["reserved"]
        if reserved + amount_cents > order["paid_cents"]:
            raise ConflictError("refund amount exceeds paid amount")

        conn.execute(
            "INSERT INTO refunds(tenant, refund_id, order_id, amount_cents, reason, status) "
            "VALUES(?,?,?,?,?,'pending')",
            (tenant, refund_id, order_id, amount_cents, reason),
        )
        conn.execute("COMMIT")
    except Exception:
        _rollback(conn)
        raise
    finally:
        conn.close()
    return get(tenant, refund_id), True


def review(tenant: str, refund_id: str, approve: bool) -> dict | None:
    """审核退款单：同意则对订单生效，拒绝则关闭。审核结果不可覆盖，重复审核返回原结果。"""
    conn = connect()
    try:
        conn.execute("BEGIN IMMEDIATE")
        row = conn.execute(
            "SELECT tenant, refund_id, order_id, amount_cents, reason, status "
            "FROM refunds WHERE tenant=? AND refund_id=?",
            (tenant, refund_id),
        ).fetchone()
        if row is None:
            _rollback(conn)
            return None
        if row["status"] in (APPROVED, REJECTED):
            conn.execute("COMMIT")
            return _to_dict(row)
        if row["status"] == REVERSED:
            raise ConflictError("refund already reversed")

        if approve:
            order = conn.execute(
                "SELECT amount_cents, paid_cents FROM orders WHERE tenant=? AND order_id=?",
                (tenant, row["order_id"]),
            ).fetchone()
            net_approved_total = conn.execute(
                "SELECT COALESCE(SUM(amount_cents),0) AS total FROM refunds "
                "WHERE tenant=? AND order_id=? AND status='approved'",
                (tenant, row["order_id"]),
            ).fetchone()["total"]
            if order is None or net_approved_total + row["amount_cents"] > order["paid_cents"]:
                raise ConflictError("refund exceeds paid amount")
            # 退款生效后净已收严格小于订单金额，订单回到有待收余额的状态。
            conn.execute(
                "UPDATE orders SET status='accepted' WHERE tenant=? AND order_id=?",
                (tenant, row["order_id"]),
            )

        new_status = APPROVED if approve else REJECTED
        conn.execute(
            "UPDATE refunds SET status=? WHERE tenant=? AND refund_id=?",
            (new_status, tenant, refund_id),
        )
        conn.execute("COMMIT")
    except Exception:
        _rollback(conn)
        raise
    finally:
        conn.close()
    return get(tenant, refund_id)


def reverse(tenant: str, refund_id: str) -> dict | None:
    """冲正已生效退款单：金额全额反向退回订单，单据置为已冲正，此后不可再审核。"""
    conn = connect()
    try:
        conn.execute("BEGIN IMMEDIATE")
        row = conn.execute(
            "SELECT order_id, amount_cents, status FROM refunds WHERE tenant=? AND refund_id=?",
            (tenant, refund_id),
        ).fetchone()
        if row is None:
            _rollback(conn)
            return None
        if row["status"] == REVERSED:
            raise ConflictError("refund already reversed")
        if row["status"] != APPROVED:
            raise ConflictError("refund not effective")

        # 防御性守恒检查：冲正会把该笔金额加回净已收，若已通过收款补回该额度，
        # 冲正后净已收将超过订单金额，此时拒绝冲正，保持账务闭合。
        order = conn.execute(
            "SELECT amount_cents, paid_cents FROM orders WHERE tenant=? AND order_id=?",
            (tenant, row["order_id"]),
        ).fetchone()
        approved_total = conn.execute(
            "SELECT COALESCE(SUM(amount_cents),0) AS total FROM refunds "
            "WHERE tenant=? AND order_id=? AND status='approved'",
            (tenant, row["order_id"]),
        ).fetchone()["total"]
        if order is not None and order["paid_cents"] - approved_total + row["amount_cents"] > order["amount_cents"]:
            raise ConflictError("reverse would exceed order amount")

        conn.execute(
            "UPDATE refunds SET status='reversed' WHERE tenant=? AND refund_id=?",
            (tenant, refund_id),
        )
        new_net_paid = order["paid_cents"] - approved_total + row["amount_cents"]
        new_status = "settled" if new_net_paid >= order["amount_cents"] else "accepted"
        conn.execute(
            "UPDATE orders SET status=? WHERE tenant=? AND order_id=?",
            (new_status, tenant, row["order_id"]),
        )
        conn.execute("COMMIT")
    except Exception:
        _rollback(conn)
        raise
    finally:
        conn.close()
    return get(tenant, refund_id)


def net_approved(tenant: str, order_id: str) -> int:
    """订单已批准且未冲正的退款总额，即已从已收金额中实际扣减的部分。"""
    conn = connect()
    try:
        return conn.execute(
            "SELECT COALESCE(SUM(amount_cents),0) AS total FROM refunds "
            "WHERE tenant=? AND order_id=? AND status='approved'",
            (tenant, order_id),
        ).fetchone()["total"]
    finally:
        conn.close()

import csv
import io
import re

from app.rules.order_rules import ALLOWED_CURRENCIES
from app.store import batches

HEADER = ["tenant", "order_id", "amount_cents", "currency"]
_AMOUNT_RE = re.compile(r"[0-9]+")


class CsvFormatError(Exception):
    """CSV 结构层面非法：缺表头、列数不符、编码非法、行结构损坏，需整批拒绝。"""


def parse_rows(raw: bytes) -> list[tuple[int, list[str]]]:
    """严格解析 CSV，返回(物理行号, 四列字段)数据行列表；任何结构问题抛 CsvFormatError。"""
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as error:
        raise CsvFormatError("csv must be valid UTF-8 text") from error
    reader = csv.reader(io.StringIO(text), strict=True)
    rows: list[tuple[int, list[str]]] = []
    try:
        header = next(reader, None)
        if header is None or [field.strip() for field in header] != HEADER:
            raise CsvFormatError("csv header must be exactly: tenant,order_id,amount_cents,currency")
        for row in reader:
            line_no = reader.line_num
            if len(row) != len(HEADER):
                raise CsvFormatError(f"line {line_no}: expected {len(HEADER)} columns, got {len(row)}")
            rows.append((line_no, row))
    except csv.Error as error:
        # 引号未闭合等损坏行结构。
        raise CsvFormatError(f"malformed csv structure: {error}") from error
    return rows


def _validate_row(declared_tenant: str, fields: list[str]) -> tuple[str, int, str] | str:
    """返回(order_id, amount_cents, currency)表示通过；否则返回错误描述。"""
    tenant, order_id, amount_text, currency = fields
    if not tenant or tenant != declared_tenant:
        return "row tenant must match the tenant declared by the request"
    if not order_id.strip():
        return "order_id is required"
    if _AMOUNT_RE.fullmatch(amount_text) is None or int(amount_text) <= 0:
        return "amount_cents must be a positive integer in the smallest currency unit"
    if currency not in ALLOWED_CURRENCIES:
        return f"unsupported currency: {currency}"
    return order_id, int(amount_text), currency


def accept_batch(tenant: str, batch_id: str, raw: bytes) -> tuple[dict, bool]:
    """受理一个批次，返回(批次结果, 本次是否实际处理)。

    批次身份为（租户, batch_id）：终态批次重放只返回既有结果、不再受理任何行；
    进行中批次按行断点续跑，每行在独立事务内提交，崩溃不回滚已提交行。
    """
    rows = parse_rows(raw)
    _, mode = batches.ensure(tenant, batch_id, len(rows), raw)
    if mode == "terminal":
